    "Key Concepts": [
      {
        "Concept": "Unperturbed system",
        "Explanation": "A system with a Hamiltonian H0 whose eigenvalues and eigenfunctions are known exactly."
      },
      {
        "Concept": "Perturbation",
        "Explanation": "A small additional term H' added to the Hamiltonian to represent a weak external field or interaction."
      },
