          "left_child": 20,
          "right_child": 40
        },
        "right_subtree": {
          "root": 70,
          "left_child": 60,
          "right_child": 80
        }
      },
      "inorder_traversal": [
        20,
        30,
        40,
        50,
        60,
        70,
        80
      ],
      "search_example": {
        "target": 60,
        "search_path": [
          50,
          70,
          60
        ],
        "result": "Found"
      }
    },
    "pseudocode": {
      "search": [
        "BST_Search(root, key):",
        "    if root is null:",
        "        return null",
        "    if key == root.key:",
        "        return root",
        "    else if key < root.key:",
        "        return BST_Search(root.left, key)",
        "    else:",
        "        return BST_Search(root.right, key)"
      ],
      "insert": [
        "BST_Insert(root, key):",
        "    if root is null:",
        "        return new Node(key)",
        "    if key < root.key:",
        "        root.left = BST_Insert(root.left, key)",
        "    else if key > root.key:",
        "        root.right = BST_Insert(root.right, key)",
        "    return root"
      ],
      "inorder_traversal": [
        "Inorder(root):",
        "    if root is not null:",
        "        Inorder(root.left)",
        "        visit(root)",
        "        Inorder(root.right)"
      ]
    },
    "assessment_design": {
      "formative_assessment": [
        "Ask students to identify whether a given tree is a BST.",
        "Ask students to trace the insertion of a new node.",
        "Ask students to explain why inorder traversal produces sorted order.",
        "Use quick quizzes to check understanding of deletion cases."
      ],
      "summative_assessment": [
        {
          "question": "Construct a BST by inserting the sequence 45, 25, 65, 15, 35, 55, 75.",
          "expected_answer": "A BST with root 45; left subtree rooted at 25 with children 15 and 35; right subtree rooted at 65 with children 55 and 75."
        },
        {
          "question": "Give the inorder traversal of the constructed BST.",
          "expected_answer": "15, 25, 35, 45, 55, 65, 75."
        },
        {
          "question": "What is the worst-case time complexity of searching in a BST? Why?",
          "expected_answer": "O(n), because the BST may become completely skewed and behave like a linked list."
        },
        {
          "question": "Describe how to delete a node with two children from a BST.",
          "expected_answer": "Replace it with its inorder successor or inorder predecessor, then delete that successor or predecessor from its original position."
        }
      ]
    },
    "common_misconceptions": [
      {
        "misconception": "Only the immediate left child must be smaller and the immediate right child must be larger.",
        "correction": "All nodes in the entire left subtree must be smaller, and all nodes in the entire right subtree must be larger."
      },
      {
        "misconception": "BST operations are always O(log n).",
        "correction": "They are O(log n) only when the tree is balanced. In the worst case, they are O(n)."
      },
      {
        "misconception": "Deleting a node with two children means simply removing it.",
        "correction": "The BST property must be preserved, so the node should be replaced with its inorder successor or predecessor."
      },
      {
        "misconception": "Preorder traversal of a BST gives sorted order.",
        "correction": "Inorder traversal gives sorted order."
      }
    ],
