        "problem": "0/1 Knapsack",
        "dp_state": "dp[i][w] represents the maximum value using the first i items with capacity w.",
        "transition": "dp[i][w] = max(dp[i - 1][w], dp[i - 1][w - weight[i]] + value[i]) if w >= weight[i]",
        "base_cases": [
          "dp[0][w] = 0",
          "dp[i][0] = 0"
        ],
        "complexity": {
          "time": "O(nW)",
          "space": "O(nW), can be optimized to O(W)"
        }
      },
      {
        "problem": "Longest Common Subsequence",
        "dp_state": "dp[i][j] represents the length of the LCS of the first i characters of string A and the first j characters of string B.",
        "transition": "If A[i - 1] == B[j - 1], dp[i][j] = dp[i - 1][j - 1] + 1; otherwise dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])",
        "base_cases": [
          "dp[0][j] = 0",
          "dp[i][0] = 0"
        ],
        "complexity": {
          "time": "O(mn)",
          "space": "O(mn), can sometimes be optimized to O(min(m, n))"
        }
      },
      {
        "problem": "Matrix Chain Multiplication",
        "dp_state": "dp[i][j] represents the minimum number of scalar multiplications needed to multiply matrices from i to j.",
        "transition": "dp[i][j] = min(dp[i][k] + dp[k + 1][j] + cost(i, k, j)) for i <= k < j",
        "base_cases": [
          "dp[i][i] = 0"
        ],
        "complexity": {
          "time": "O(n^3)",
          "space": "O(n^2)"
        }
      }
