    "common_misconceptions": [
      {
        "misconception": "Dynamic programming is just recursion with caching.",
        "correction": "Memoization is one form of DP, but bottom-up tabulation is also widely used. DP is a general method based on subproblem structure."
      },
      {
        "misconception": "All optimization problems can be solved using DP.",
        "correction": "DP requires properties such as optimal substructure and manageable state space."
      },
      {
        "misconception": "Greedy and DP are interchangeable.",
        "correction": "Greedy makes locally optimal choices, while DP systematically explores subproblem combinations."
      },
      {
        "misconception": "The DP table must always be two-dimensional.",
        "correction": "DP states can be one-dimensional, two-dimensional, multi-dimensional, tree-structured, or compressed into bitmasks."
      },
      {
        "misconception": "Space optimization is always safe.",
        "correction": "Space optimization must preserve the correct dependency order."
      }
