      {
        "term": "Genomic Estimated Breeding Value",
        "definition": "The predicted genetic value of an individual calculated from genome-wide marker information and a trained statistical model."
      },
      {
        "term": "Training Population",
        "definition": "A population with both genotype and phenotype data used to train the genomic prediction model."
      },
      {
        "term": "Prediction Population",
        "definition": "A group of individuals with genotype data but little or no phenotype data, whose breeding values are predicted using the trained model."
      },
      {
        "term": "Prediction Accuracy",
        "definition": "The correlation between predicted breeding values and true or observed genetic values, often used to evaluate genomic selection performance."
      },
      {
        "term": "Marker-Assisted Selection",
        "definition": "A selection method using a small number of markers linked to major genes or QTLs, usually most effective for traits controlled by one or a few loci."
