    "knowledge_point": "Social Stratification and Class Theory",
    "target_learners": "Undergraduate students or senior secondary students studying sociology, social sciences, or civics",
    "teaching_duration": "1–2 class periods, approximately 45–90 minutes",
    "teaching_objectives": {
      "knowledge_objectives": [
        "Understand the meaning of social stratification and its major forms.",
        "Explain key concepts such as social class, status, power, social mobility, inequality, and life chances.",
        "Identify major theories of class and stratification, including Marxist theory, Weberian theory, and functionalist theory.",
        "Recognize how social stratification operates in areas such as education, occupation, income, gender, ethnicity, and family background."
      ],
      "ability_objectives": [
        "Analyze real-life examples of inequality using class and stratification theories.",
        "Compare different theoretical perspectives on why social stratification exists.",
        "Interpret simple data related to income, education, occupation, or social mobility.",
        "Develop critical thinking skills by evaluating whether social stratification is necessary, fair, or changeable."
      ],
      "value_objectives": [
        "Develop awareness of social inequality and its effects on individuals and groups.",
        "Encourage respect for diverse social backgrounds and experiences.",
        "Promote social responsibility and reflection on fairness, opportunity, and justice."
      ]
    },
    "key_concepts": [
      {
        "term": "Social Stratification",
        "definition": "The structured ranking of individuals or groups in society based on unequal access to resources, power, prestige, and opportunities."
      },
      {
        "term": "Social Class",
        "definition": "A group of people who share a similar economic position, usually related to income, wealth, occupation, and education."
      },
      {
        "term": "Class Theory",
        "definition": "A set of sociological explanations about how classes are formed, maintained, and transformed in society."
      },
      {
        "term": "Social Mobility",
        "definition": "The movement of individuals or groups from one social position to another within a stratification system."
      },
      {
        "term": "Life Chances",
        "definition": "The opportunities individuals have to obtain resources and achieve desired outcomes, such as education, health, employment, and security."
      },
      {
        "term": "Inequality",
        "definition": "Unequal distribution of valued resources, opportunities, and rewards among members of society."
      }
    ],
    "key_points": [
      "Social stratification is a universal but historically variable feature of human societies.",
      "Social stratification involves inequality in wealth, power, prestige, and opportunity.",
      "Class is one important dimension of stratification, but it interacts with gender, ethnicity, race, age, region, and other social factors.",
      "Karl Marx emphasized economic relations, ownership of the means of production, class conflict, and exploitation.",
      "Max Weber argued that stratification has multiple dimensions: class, status, and party or power.",
      "Functionalist theorists argue that stratification can serve social functions by allocating roles and motivating achievement, though this view is often criticized.",
      "Social mobility can be upward, downward, intergenerational, or intragenerational.",
      "Education, family background, labor markets, public policy, and cultural capital influence class position and mobility."
    ],
    "teaching_difficulties": [
      {
        "difficulty": "Distinguishing class from status and power",
        "strategy": "Use concrete examples, such as a wealthy businessperson, a respected teacher, and a political official, to show differences among economic resources, prestige, and authority."
      },
      {
        "difficulty": "Understanding abstract theories such as Marxism and Weberian theory",
        "strategy": "Use comparison tables and real-life cases to connect theory with social reality."
      },
      {
        "difficulty": "Avoiding overly simplistic explanations of poverty and inequality",
        "strategy": "Guide students to consider both individual factors and structural factors, such as family background, education systems, labor markets, and discrimination."
      },
      {
        "difficulty": "Discussing inequality sensitively",
        "strategy": "Establish respectful discussion rules and remind students that social class is a structural topic rather than a judgment of individual worth."
      }
    ],
    "theoretical_framework": {
      "Marxist_class_theory": {
        "main_ideas": [
          "Society is divided into classes based on relationship to the means of production.",
          "In capitalist society, the main classes are the bourgeoisie, who own capital, and the proletariat, who sell their labor.",
          "Class conflict is the driving force of social change.",
          "Economic exploitation and unequal control of resources create class inequality."
        ],
        "classroom_example": "Factory owners earn profit from production, while workers receive wages. Marxist theory asks who controls production and who benefits from labor."
      },
      "Weberian_stratification_theory": {
        "main_ideas": [
          "Stratification is multidimensional.",
          "Class refers to economic position and market situation.",
          "Status refers to social honor or prestige.",
          "Party or power refers to the ability to influence collective decisions."
        ],
        "classroom_example": "A famous artist may have high status but not necessarily high wealth; a government official may have significant power even if not among the richest."
      },
      "Functionalist_theory": {
        "main_ideas": [
          "Stratification may help society allocate important roles.",
          "Higher rewards may motivate individuals to obtain skills and perform difficult tasks.",
          "Social inequality is seen as serving a function, though this perspective is often criticized for justifying inequality."
        ],
        "classroom_example": "Doctors often receive high income because their training is long and their work is socially important. Students can debate whether this fully explains income inequality."
      },
      "Conflict_and_critical_perspectives": {
        "main_ideas": [
          "Inequality is often maintained by institutions, ideology, and unequal power.",
          "Social class intersects with gender, race, ethnicity, and other identities.",
          "Education and culture may reproduce class advantages across generations."
        ],
        "classroom_example": "Students from wealthy families may have access to better schools, tutoring, social networks, and career opportunities."
      }
    },
    "classroom_activity_design": {
      "activity_1_warm_up": {
        "title": "Who Gets What and Why?",
        "time": "10 minutes",
        "procedure": [
          "Show students several occupations, such as doctor, cleaner, teacher, entrepreneur, delivery worker, lawyer, and artist.",
          "Ask students to rank them according to income, prestige, and power.",
          "Invite students to compare whether the rankings are the same or different.",
          "Introduce the idea that stratification involves multiple dimensions."
        ],
        "purpose": "Activate prior knowledge and introduce class, status, and power."
      },
      "activity_2_concept_mapping": {
        "title": "Mapping Social Stratification",
        "time": "15 minutes",
        "procedure": [
          "Divide students into small groups.",
          "Give each group key terms: class, wealth, income, education, occupation, status, power, mobility, inequality, life chances.",
          "Ask groups to create a concept map showing how the terms are connected.",
          "Each group presents its map briefly."
        ],
        "purpose": "Help students build conceptual understanding and see relationships among terms."
      },
      "activity_3_theory_comparison": {
        "title": "Marx, Weber, and Functionalism",
        "time": "20 minutes",
        "procedure": [
          "Provide a short case: A society has business owners, highly paid professionals, low-wage service workers, celebrities, and political leaders.",
          "Assign each group one theoretical perspective: Marxist, Weberian, or functionalist.",
          "Ask groups to analyze the case from their assigned perspective.",
          "Groups answer three questions: What causes inequality? Who benefits? Is inequality necessary or problematic?",
          "Conduct a whole-class comparison."
        ],
        "purpose": "Develop theoretical application and comparison skills."
      },
      "activity_4_social_mobility_simulation": {
        "title": "The Mobility Ladder",
        "time": "20 minutes",
        "procedure": [
          "Give students fictional character cards with different family backgrounds, education levels, neighborhoods, health conditions, and social networks.",
          "Read out life events, such as receiving a scholarship, losing a job, facing discrimination, gaining inheritance, or accessing professional networks.",
          "Students move up or down a symbolic ladder according to how events affect their character.",
          "Discuss which factors helped or limited mobility."
        ],
        "purpose": "Illustrate how social mobility is shaped by both individual effort and structural conditions."
      },
      "activity_5_debate": {
        "title": "Is Social Stratification Inevitable?",
        "time": "15–20 minutes",
        "procedure": [
          "Divide the class into two sides: one argues that social stratification is inevitable or functional; the other argues that it is unjust and should be reduced.",
          "Students prepare arguments using theories and examples.",
          "Hold a structured debate with opening statements, rebuttals, and concluding remarks.",
          "Teacher summarizes the strengths and limitations of each argument."
        ],
        "purpose": "Encourage critical thinking, argumentation, and evaluation of theory."
      }
    },
    "teaching_process": [
      {
        "stage": "Introduction",
        "time": "5–10 minutes",
        "teacher_activity": "Present everyday examples of inequality in income, education, housing, and occupation.",
        "student_activity": "Share observations and initial explanations.",
        "teaching_intention": "Connect the topic to students' lived experiences."
      },
      {
        "stage": "Concept Explanation",
        "time": "15 minutes",
