        "teaching_intention": "Help students understand different explanations of inequality."
      },
      {
        "stage": "Application Activity",
        "time": "20 minutes",
        "teacher_activity": "Organize case analysis or social mobility simulation.",
        "student_activity": "Apply theories to real or fictional cases.",
        "teaching_intention": "Develop analytical and practical application skills."
