      {
        "stage": "Discussion and Reflection",
        "time": "10–15 minutes",
        "teacher_activity": "Guide discussion on fairness, opportunity, and social policy.",
        "student_activity": "Express viewpoints using sociological concepts.",
        "teaching_intention": "Encourage critical reflection and value education."
      },
      {
        "stage": "Summary and Assessment",
        "time": "5–10 minutes",
        "teacher_activity": "Summarize key concepts and assign exit ticket or short writing task.",
        "student_activity": "Complete quick assessment.",
        "teaching_intention": "Check understanding and consolidate learning."
      }
    ],
    "teaching_methods": [
      "Lecture with examples",
      "Group discussion",
      "Case analysis",
      "Role play or simulation",
      "Debate",
      "Data interpretation",
      "Reflective writing"
